$$
\begin{aligned}
\binom{2n}{n+10} &\approx \frac{\left(\frac{2n}{e}\right)^{2n}\sqrt{2\pi(2n)}}{(n+10)!\cdot(n-10)!}\\
&= \frac{\left(\frac{2n}{e}\right)^{2n}\sqrt{2\pi(2n)}}{\left(\frac{n+10}{e}\right)^{n+10}\sqrt{2\pi(n+10)}\cdot\left(\frac{n-10}{e}\right)^{n-10}\sqrt{2\pi(n-10)}}
\end{aligned}
$$

Simplifying further, we get:

$$
\begin{aligned}
\binom{2n}{n+10} &\approx \frac{\left(\frac{2n}{e}\right)^{2n}}{\left(\frac{n+10}{e}\right)^{n+10}\cdot\left(\frac{n-10}{e}\right)^{n-10}}\cdot\sqrt{\frac{(2n)}{(n+10)\cdot(n-10)}}\\
